import {bondPrice} from './calculations.js';
const TRIAL_KEY='finance-bond-trials-v1';
const trialMoney=x=>'$'+x.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
export const bondTrials=[
 {id:'promise',title:'The promise',subtitle:'What buying a bond actually means',focus:'Separate the money you lend, the interest you receive, and the repayment at the end.',steps:[
  {type:'story',label:'Start with a situation',title:'Maya lends a workshop $1,000.',paragraphs:['Cedar Workshop needs money for equipment. It issues a three-year bond, and Maya buys it for $1,000. Maya is lending money to the company.','The contract promises $50 of interest each year, then repayment of the $1,000 principal at the end of year three. We will follow this same bond in all three lessons.'],takeaway:'A bond is a promise of future payments. Start by following the money.'},
  {type:'example',label:'Follow the money',title:'One loan. Two kinds of payment.',paragraphs:['The face value is the $1,000 principal promised back at maturity. The coupon payment is the $50 of interest paid each year. The coupon rate is 5% because $50 is 5% of $1,000.','At the end of year three, Maya receives the last $50 coupon AND the $1,000 principal.'],timeline:true,takeaway:'“Coupon rate” is a percentage; “coupon payment” is an amount of money.'},
  {type:'check',label:'One small check',title:'How much arrives in the final year?',paragraphs:['Keep Maya’s contract in view: a $50 yearly coupon, plus $1,000 principal repaid at the end of year three.'],question:'What is the total final payment?',options:['$1,000','$1,050','$150'],correct:1,explanation:'The final payment combines the last $50 coupon with $1,000 principal: $50 + $1,000 = $1,050. The earlier two coupons were paid in their own years.',timeline:true},
  {type:'check',label:'Keep the distinction',title:'Maya sells the bond to Noah.',paragraphs:['Maya sells this same bond to Noah for $980. The company is not a party to this resale; assume its contract stays unchanged.'],question:'Which amount does the company still promise to repay as principal at maturity?',options:['$980, because that is Noah’s purchase price','$1,000, because that is the bond’s contractual face value','$1,050, because that is all principal'],correct:1,explanation:'Face value remains $1,000. The resale price is money Noah pays Maya; it does not rewrite what the company owes. The final $1,050 includes both interest and principal.'}
 ]},
 {id:'price',title:'The price can change',subtitle:'Why bond prices move when required returns change',focus:'The promise stays fixed while buyers decide what they will pay for it.',steps:[
  {type:'story',label:'A quick reminder',title:'Same bond. Same promised payments.',paragraphs:['Return to the moment the bond has three years remaining. It promises $50 annually and $1,000 principal at maturity. At a 5% required annual yield, its price is $1,000.','“Required yield” means the return investors require at the price they pay. Prices in the market imply yields. The company does not centrally impose a market yield on buyers.'],takeaway:'A market price can change without the contract changing.'},
  {type:'example',label:'Build the intuition',title:'What if buyers require a higher return?',paragraphs:['Suppose prices of comparable bonds now imply a 6% annual yield. Buyers want the same return for Maya’s bond, assuming comparable risk and terms.','This bond still promises only $50 coupons and $1,000 principal. A lower purchase price gives the buyer a higher return from those unchanged payments. At a 6% yield, its three-year price is about $973.27.'],comparison:true,takeaway:'Higher required yield → lower price, for unchanged fixed payments.'},
  {type:'check',label:'Predict one change',title:'Required yield rises again.',paragraphs:['Keep the same three-year bond and its fixed payments. Buyers now require 7% instead of 6%.'],question:'Which price direction would give buyers that higher yield?',options:['A higher price','A lower price','The company must raise its coupon payment'],correct:1,explanation:'A lower price. With the same future payments, paying less raises the buyer’s implied yield. At 7%, this example’s price is about $947.51. The coupon stays $50.'},
  {type:'explore',label:'See the relationship',title:'Move the required yield.',paragraphs:['The payments below stay fixed. Move the slider and watch the price investors would pay under this simple pricing model. You do not need to memorize or calculate these prices.'],takeaway:'The market price adjusts; the promised coupon and principal do not.'},
  {type:'check',label:'Try the reverse',title:'Now buyers accept a lower yield.',paragraphs:['Use the same bond. Buyers’ required yield falls from 5% to 4%. Its promised payments remain $50 annually and $1,000 principal.'],question:'What happens to its price in this model?',options:['It rises above $1,000','It falls below $1,000','The $50 coupon automatically falls'],correct:0,explanation:'Its price rises above $1,000—to about $1,027.75. Buyers accepting a lower yield can pay more for the unchanged payments.'}
 ]},
 {id:'yield',title:'Make the price make sense',subtitle:'One remaining payment, one simple calculation',focus:'Connect a lower purchase price to a higher return without tackling a long formula.',steps:[
  {type:'story',label:'Bring the story forward',title:'Two years have passed.',paragraphs:['Maya has already received two $50 coupons. There is now exactly one year until the last $1,050 payment: $50 interest plus $1,000 principal.','Those earlier coupons are history for a new buyer. Someone buying the bond today pays for the one payment still to come. Assume the company pays in full, and ignore taxes, fees and accrued interest.'],remaining:true,takeaway:'Today’s price values the payments still ahead, not payments already received.'},
  {type:'example',label:'A complete worked example',title:'What price gives a 6% one-year return?',paragraphs:['The buyer needs today’s price to grow by 6% into the final $1,050 payment. So divide the final payment by 1.06.','Price today = $1,050 ÷ 1.06 = $990.57 (rounded). Paying about $990.57 and receiving $1,050 produces a 6% return over this final year, if paid as promised.'],simpleFormula:true,remaining:true,takeaway:'Coupon rate stays 5%; buying at a discount can produce a 6% yield.'},
  {type:'check',label:'Complete one familiar step',title:'Change just the required return.',paragraphs:['There is still one year left and the final payment is still $1,050. This time the buyer requires a 10% one-year return. Use the equation below; a calculator is welcome.'],simpleFormula:true,question:'Which purchase price gives that 10% return?',options:['$954.55','$1,000','$1,050'],correct:0,explanation:'Price = $1,050 ÷ 1.10 = about $954.55. The exact unrounded price grows by 10% into $1,050. A higher required return means a lower price.'},
  {type:'check',label:'Connect the idea',title:'Why can yield differ from coupon rate?',paragraphs:['Return to the 6% example: the annual coupon remains $50 on $1,000 face value, and the purchase price with one year left is about $990.57.'],question:'Where does the buyer’s 6% one-year return come from?',options:['The company changes the coupon rate to 6%','The $50 coupon plus receiving more principal than the discounted purchase price','A guarantee that every risky bond earns 6%'],correct:1,explanation:'The buyer receives $50 interest and $1,000 principal after paying about $990.57. The coupon plus the gain from buying below face value creates the 6% one-year return. This assumes the promised payment arrives; it does not guarantee a risky issuer will pay.'}
 ]}
];
export function mountBondTrials(root,route,{escape:escapeTrial,notify}){
 let records={},blocked=false,readNotice='';
 try{const raw=localStorage.getItem(TRIAL_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.version!==1||!parsed.lessons||typeof parsed.lessons!=='object')throw Error('Invalid trial progress');
  for(const lesson of bondTrials){const r=parsed.lessons[lesson.id];if(!r)continue;if(!Number.isInteger(r.step)||r.step<0||r.step>lesson.steps.length||!r.answers||typeof r.answers!=='object')throw Error('Invalid trial step');
   const answers={};for(const [i,a] of Object.entries(r.answers)){const step=lesson.steps[Number(i)];if(!step||step.type!=='check'||!a||typeof a.revealed!=='boolean'||(a.choice!==null&&(!Number.isInteger(a.choice)||!step.options[a.choice])))throw Error('Invalid trial answer');answers[i]={choice:a.choice,revealed:a.revealed};}
   records[lesson.id]={step:r.step,answers,finished:typeof r.finished==='number'?r.finished:null,reflection:['lighter','similar','heavy'].includes(r.reflection)?r.reflection:null};
  }
 }}catch{blocked=true;readNotice='Trial progress could not be read. You can still explore; the original saved trial data will stay untouched.';}
 const store=()=>{if(blocked)return;try{localStorage.setItem(TRIAL_KEY,JSON.stringify({version:1,lessons:records}));}catch{notify('Trial progress could not be saved on this browser.');}};
 const go=id=>{location.hash=id?'trial/'+id:'trials';};
 const lesson=bondTrials.find(l=>route==='trial/'+l.id);
 const context=l=>`<aside class="trial-context"><span class="eyebrow">OUR BOND, AT A GLANCE</span><h3>Cedar Workshop → Maya</h3><dl><div><dt>Face value · principal</dt><dd>$1,000</dd></div><div><dt>Yearly coupon · interest</dt><dd>$50</dd></div><div><dt>Coupon rate</dt><dd>5%</dd></div><div><dt>Payments still ahead</dt><dd>${l.id==='yield'?'One $1,050 payment in one year':'$50 in years 1 and 2;<br>$1,050 in year 3'}</dd></div></dl><p class="small muted">${l.id==='yield'?'The first two coupons have already been paid.':'Three-year bond with annual coupons.'} Examples assume full payment and ignore taxes and fees.</p></aside>`;
 const notice=readNotice?`<p class="errorbanner">${escapeTrial(readNotice)}</p>`:'';
 const timeline=()=>`<div class="trial-timeline" aria-label="Bond payment timeline"><div><span>YEAR 1</span><strong>$50</strong><small>coupon</small></div><div><span>YEAR 2</span><strong>$50</strong><small>coupon</small></div><div><span>YEAR 3</span><strong>$1,050</strong><small>$50 coupon + $1,000 principal</small></div></div>`;
 const simpleFormula=()=>`<div class="formula">Price today = final payment ÷ (1 + required one-year return)</div><p class="small muted">Enter the return as a decimal: 6% is 0.06; 10% is 0.10. The “1” represents returning the money originally invested.</p>`;
 if(!lesson){root.innerHTML=notice+`<div class="trial-intro"><span class="pill">A three-lesson trial</span><h1>One bond.<br>A story you can follow.</h1><p class="muted">Start with a reminder, follow a worked example, then try a small connected question. The situation stays in view while you think.</p><p class="small muted">Try one lesson a day, or preview all three. Each is designed for a few minutes. You can reveal explanations at any time.</p></div><div class="grid">${bondTrials.map((l,i)=>{const r=records[l.id];return `<article class="tile trial-tile"><span class="eyebrow">LESSON ${i+1} · ${r?.finished?'EXPLORED':r?.step?'IN PROGRESS':'START HERE'}</span><h2>${escapeTrial(l.title)}</h2><p>${escapeTrial(l.subtitle)}</p><p class="small muted">${escapeTrial(l.focus)}</p><button class="primary" data-trial-open="${l.id}">${r?.finished?'Revisit lesson':r?.step?'Continue lesson':'Start lesson'} →</button></article>`;}).join('')}</div><div class="callout" style="margin-top:26px"><p><strong>Understanding first, with gentle practice.</strong></p><p>Your choices get immediate explanations. These trial lessons keep their own progress and do not change your card-review schedule.</p></div>`;
  root.querySelectorAll('[data-trial-open]').forEach(b=>b.onclick=()=>{const l=bondTrials.find(l=>l.id===b.dataset.trialOpen);const r=records[l.id];if(r?.finished){r.step=0;r.answers={};r.finished=null;store();}go(l.id);});return;
 }
 const record=records[lesson.id]||(records[lesson.id]={step:0,answers:{},finished:null,reflection:null});
 function renderLesson(){const index=record.step;
  if(index===lesson.steps.length){record.finished=record.finished||Date.now();store();const next=bondTrials[bondTrials.indexOf(lesson)+1];root.innerHTML=notice+`<div class="study"><a class="back" href="#trials">← All three lessons</a><article class="studycard"><span class="eyebrow">LESSON EXPLORED</span><h1>${escapeTrial(lesson.title)}</h1><p>${escapeTrial(lesson.focus)}</p><div class="callout"><p><strong>${escapeTrial(lesson.id==='promise'?'Face value, coupon payment and purchase price are different things.':lesson.id==='price'?'Fixed payments can stay the same while market prices and yields change.':'A discounted purchase price can make yield higher than the coupon rate.')}</strong></p></div><h3>How did this feel?</h3><p class="small muted">This helps you compare the trial with the earlier questions. It is saved only on this device.</p><div class="actions">${[['lighter','Lighter'],['similar','About the same'],['heavy','Still too heavy']].map(([v,t])=>`<button data-trial-reflection="${v}" aria-pressed="${record.reflection===v}">${t}</button>`).join('')}</div>${record.reflection?'<p class="small muted" role="status">Your impression is saved. There is no need to keep going today.</p>':''}<div class="actions"><button id="trial-revisit">Revisit this lesson</button><a class="button primary" href="${next?'#trial/'+next.id:'#trials'}">${next?'Preview the next lesson →':'Back to all lessons'}</a></div><p class="small muted">${next?'A break is welcome. The next lesson begins with a reminder of the same bond.':'You have seen the trial format. Keep the review app available while deciding whether this approach suits you.'}</p></article></div>`;
   root.querySelectorAll('[data-trial-reflection]').forEach(b=>b.onclick=()=>{record.reflection=b.dataset.trialReflection;store();renderLesson();});root.querySelector('#trial-revisit').onclick=()=>{record.step=0;record.answers={};record.finished=null;store();renderLesson();};return;
  }
  const step=lesson.steps[index],answer=record.answers[index],revealed=!!answer?.revealed;root.innerHTML=notice+`<div class="trial-header"><a class="back" href="#trials">← Save & leave</a><span class="small muted">${escapeTrial(lesson.title)} · ${index+1} of ${lesson.steps.length} steps</span></div><div class="meter"><span style="width:${index/lesson.steps.length*100}%"></span></div><div class="trial-layout"><article class="studycard trial-main"><span class="eyebrow">${escapeTrial(step.label)}</span><h2 id="trial-heading" tabindex="-1">${escapeTrial(step.title)}</h2>${step.paragraphs.map(p=>`<p>${escapeTrial(p)}</p>`).join('')}${step.timeline?timeline():''}${step.remaining?'<div class="trial-payment"><span>TODAY</span><strong>Price paid →</strong><span>ONE YEAR LATER</span><strong>$1,050 received</strong></div>':''}${step.simpleFormula?simpleFormula():''}${step.comparison?'<div class="trial-comparison"><div><span>Required yield: 5%</span><strong>$1,000.00</strong><small>price today</small></div><span aria-hidden="true">→</span><div><span>Required yield: 6%</span><strong>$973.27</strong><small>price today</small></div></div>':''}${step.type==='explore'?`<label for="trial-yield">Required annual yield: <output id="trial-rate">5.0%</output></label><input type="range" id="trial-yield" min="3" max="8" step="0.5" value="5"><div class="trial-price" aria-live="polite"><span>Price for our three-year bond</span><strong id="trial-price">$1,000.00</strong><p id="trial-observation" class="small muted">At a 5% yield, the bond trades at face value.</p></div><details><summary>Show the pricing formula</summary><div class="formula">Price = 50/(1+y) + 50/(1+y)² + 1,050/(1+y)³</div><p class="small muted">y is the required annual yield as a decimal. Each future payment is discounted for its waiting time. The final $1,050 includes principal and the last coupon.</p></details>`:''}${step.type==='check'?`<section class="trial-check"><h3>${escapeTrial(step.question)}</h3>${step.options.map((o,i)=>`<button class="choice ${revealed&&i===step.correct?'correct':''}" data-trial-choice="${i}" ${revealed?'disabled':''}>${escapeTrial(o)}</button>`).join('')}${revealed?`<div class="feedback" role="status"><strong>${answer.choice===null?'Walk through it:':answer.choice===step.correct?'Yes—here is the reason:':'Here is the distinction:'}</strong><p>${escapeTrial(step.explanation)}</p></div>`:'<button class="textbutton" id="trial-explain">Walk me through it</button>'}</section>`:''}${step.takeaway?`<div class="callout"><p>${escapeTrial(step.takeaway)}</p></div>`:''}<div class="actions"><button id="trial-back" ${index===0?'disabled':''}>← Back</button><button class="primary" id="trial-next" ${step.type==='check'&&!revealed?'disabled':''}>${index===lesson.steps.length-1?'Finish lesson':'Continue →'}</button></div></article>${context(lesson)}</div>`;
  root.querySelectorAll('[data-trial-choice]').forEach(b=>b.onclick=()=>{record.answers[index]={choice:Number(b.dataset.trialChoice),revealed:true};store();renderLesson();});root.querySelector('#trial-explain')?.addEventListener('click',()=>{record.answers[index]={choice:null,revealed:true};store();renderLesson();});root.querySelector('#trial-back').onclick=()=>{record.step--;store();renderLesson();};root.querySelector('#trial-next').onclick=()=>{record.step++;store();renderLesson();root.querySelector('#trial-heading')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});};root.querySelector('#trial-yield')?.addEventListener('input',e=>{const r=Number(e.target.value);root.querySelector('#trial-rate').textContent=r.toFixed(1)+'%';root.querySelector('#trial-price').textContent=trialMoney(bondPrice(1000,50,r/100,3));root.querySelector('#trial-observation').textContent=r===5?'At a 5% yield, the bond trades at face value.':r>5?'Higher yield, lower price. The annual coupon is still $50.':'Lower yield, higher price. The annual coupon is still $50.';});
 }
 renderLesson();
}
